package pe.edu.upeu.pago.controller; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import pe.edu.upeu.pago.dto.*; import pe.edu.upeu.pago.service.ReembolsoService; import java.util.*; @RestController @RequestMapping("/api/v1/reembolsos") @RequiredArgsConstructor public class ReembolsoController {private final ReembolsoService service;@GetMapping public List<ReembolsoResponse> listar(){return service.listar();}@PostMapping public ResponseEntity<ReembolsoResponse> solicitar(@Valid @RequestBody ReembolsoRequest r){return ResponseEntity.status(201).body(service.solicitar(r));}@PutMapping("/{id}/aprobar")public ReembolsoResponse aprobar(@PathVariable Long id){return service.aprobar(id);}@PutMapping("/{id}/rechazar")public ReembolsoResponse rechazar(@PathVariable Long id,@Valid @RequestBody RechazoRequest r){return service.rechazar(id,r.motivo());}}